{
  "vacancies": [
    {
      "fit": "green",
      "title": "AI Automation Specialist",
      "company": "Supplax",
      "wants": "n8n, інтеграції CRM, AI-агенти, англійська B1+",
      "offers": "remote, українська команда",
      "why": "n8n і AI-автоматизації — це твій профіль",
      "tip": "Підсвіти кейс з аналітикою дзвінків (n8n + AssemblyAI)",
      "link": "",
      "recruiter_email": ""
    }
  ]
}

parameters.jsCode:
const rows = $('Pre-filter').all().filter(r => !r.json.junk);
const outs = $input.all();
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDate = (d) => { const x = new Date(d); return isNaN(x) ? '' : String(x.getDate()).padStart(2, '0') + '.' + String(x.getMonth() + 1).padStart(2, '0'); };
const cleanTitle = (t) => String(t || '').replace(/\s*\((direct[^)]*|прям[^)]*|особист[^)]*)\)/ig, '').trim();
const result = [];
outs.forEach((o, i) => {
  const row = rows[i] ? rows[i].json : {};
  const vacs = ((o.json.output || {}).vacancies || []).filter(v => v && (v.fit === 'green' || v.fit === 'yellow'));
  if (row.kind === 'digest_email' || vacs.length === 0) {
    result.push({ json: { action: 'close', id: row.id } });
  }
  vacs.forEach((v, n) => {
    const direct = row.kind === 'direct';
    const link = direct ? (row.chat_link || row.link || '') : (v.link || row.link || '');
    const key = direct ? row.key : (link ? link.split('?')[0] : row.key + '-' + n);
    const emoji = v.fit === 'green' ? '🟢' : '🟡';
    const title = cleanTitle(v.title || row.title);
    const head = direct
      ? '💌 Рекрутер написав тобі' + (row.recruiter ? ' (' + esc(row.recruiter) + ')' : '')
      : '📋 Розсилка ' + esc(row.source);
    const card = [
      emoji + ' <b>' + esc(title) + (v.company || row.company ? ' — ' + esc(v.company || row.company) : '') + '</b>',
      head,
      '',
      '<b>Дата листа:</b> ' + fmtDate(row.received_at),
      '<b>Що хочуть:</b> ' + esc(v.wants),
      '<b>Що пропонують:</b> ' + esc(v.offers),
      '<b>Чому:</b> ' + esc(v.why),
      '<b>Порада:</b> ' + esc(v.tip),
      link ? '🔗 <a href="' + esc(link) + '">відкрити</a>' : '',
    ].filter((l, idx) => l !== '' || idx === 2).join('\n');
    result.push({ json: {
      action: 'card', key,
      source: row.source, kind: direct ? 'direct' : 'vacancy',
      title, company: v.company || row.company || '',
      link, chat_link: row.chat_link || '',
      recruiter: row.recruiter || '', recruiter_email: v.recruiter_email || row.recruiter_email || '',
      text: direct ? row.text : [v.wants, v.offers].join('\n'),
      received_at: row.received_at, fit: v.fit, card,
    }});
  });
});
return result;

// Сміття (коди, підтвердження, Work.ua-розсилки лише з кількістю) закриваємо без ШІ, щоб не палити ліміт Gemini
const JUNK = /підтверд|confirm|verify|код підтвердження|пароль|password/i;
return $input.all().map(it => {
  const j = it.json;
  const t = (j.title || '') + ' ' + (j.text || '').slice(0, 400);
  const countsOnly = j.source === 'Work.ua' && /За пошуковим запитом/.test(j.text || '');
  return { json: { ...j, junk: j.kind !== 'direct' && (JUNK.test(t) || countsOnly) } };
});

